-- HarvestCompass Phase 2 data model. Apply in the Supabase SQL editor or CLI.
create extension if not exists pgcrypto;
create table public.farms (id uuid primary key default gen_random_uuid(), name text not null, location text, season_year integer not null, created_at timestamptz not null default now());
create table public.farm_members (farm_id uuid not null references public.farms(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null default 'owner' check (role in ('owner','member')), primary key (farm_id,user_id));
create table public.fields (id uuid primary key default gen_random_uuid(), farm_id uuid not null references public.farms(id) on delete cascade, name text not null, crop text not null check (crop in ('Corn','Soybeans')), acres numeric(10,2) not null check (acres > 0), planted_on date, status text not null default 'On track', progress integer not null default 0 check (progress between 0 and 100), created_at timestamptz not null default now());
create table public.farm_tasks (id uuid primary key default gen_random_uuid(), farm_id uuid not null references public.farms(id) on delete cascade, title text not null, detail text not null default '', due_on date, priority text not null default 'Medium' check (priority in ('High','Medium','Low')), done boolean not null default false, created_at timestamptz not null default now());
create table public.expenses (id uuid primary key default gen_random_uuid(), farm_id uuid not null references public.farms(id) on delete cascade, category text not null check (category in ('Seed','Fertilizer','Fuel & equipment','Labor & other')), amount numeric(12,2) not null check (amount > 0), incurred_on date not null, note text not null default '', created_at timestamptz not null default now());
create table public.equipment (id uuid primary key default gen_random_uuid(), farm_id uuid not null references public.farms(id) on delete cascade, name text not null, status text not null default 'Ready' check (status in ('Ready','Needs service','In use')), note text not null default '', created_at timestamptz not null default now());
create index on public.farm_members(user_id);
create index on public.fields(farm_id);
create index on public.farm_tasks(farm_id);
create index on public.expenses(farm_id);
create index on public.equipment(farm_id);
create or replace function public.is_farm_member(target_farm uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.farm_members where farm_id=target_farm and user_id=(select auth.uid())) $$;
create or replace function public.is_farm_owner(target_farm uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.farm_members where farm_id=target_farm and user_id=(select auth.uid()) and role='owner') $$;
create or replace function public.add_farm_owner() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.farm_members(farm_id,user_id,role) values(new.id,(select auth.uid()),'owner'); return new; end $$;
create trigger farm_owner after insert on public.farms for each row execute function public.add_farm_owner();
alter table public.farms enable row level security;
alter table public.farm_members enable row level security;
alter table public.fields enable row level security;
alter table public.farm_tasks enable row level security;
alter table public.expenses enable row level security;
alter table public.equipment enable row level security;
create policy "members read farms" on public.farms for select using (public.is_farm_member(id));
create policy "signed in users create farms" on public.farms for insert to authenticated with check ((select auth.uid()) is not null);
create policy "owners update farms" on public.farms for update using (public.is_farm_owner(id));
create policy "owners delete farms" on public.farms for delete using (public.is_farm_owner(id));
create policy "members read membership" on public.farm_members for select using (public.is_farm_member(farm_id));
create policy "owners manage membership" on public.farm_members for all using (public.is_farm_owner(farm_id)) with check (public.is_farm_owner(farm_id));
create policy "members manage fields" on public.fields for all using (public.is_farm_member(farm_id)) with check (public.is_farm_member(farm_id));
create policy "members manage tasks" on public.farm_tasks for all using (public.is_farm_member(farm_id)) with check (public.is_farm_member(farm_id));
create policy "members manage expenses" on public.expenses for all using (public.is_farm_member(farm_id)) with check (public.is_farm_member(farm_id));
create policy "members manage equipment" on public.equipment for all using (public.is_farm_member(farm_id)) with check (public.is_farm_member(farm_id));
